import string

def is_valid_relative_path(s):
    if not s or s.startswith('/') or s.endswith('/'):
        return False
    allowed = set(string.ascii_letters + string.digits + '_-.')
    segments = s.split('/')
    for seg in segments:
        if not seg:
            return False
        if seg in ('.', '..'):
            return False
        if not all(c in allowed for c in seg):
            return False
    return True

import string

def is_valid_non_blocked_email(s, blocked_domains):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local:
        return False
    allowed_local = set(string.ascii_letters + string.digits + '._+-')
    if not all(c in allowed_local for c in local):
        return False
    if '.' not in domain:
        return False
    labels = domain.split('.')
    allowed_label = set(string.ascii_letters + string.digits + '-')
    for label in labels:
        if not label or not all(c in allowed_label for c in label):
            return False
    blocked_lower = [d.lower() for d in blocked_domains]
    if domain.lower() in blocked_lower:
        return False
    return True

