import string

def meets_min_digit_count_policy(s):
    if any(c.isspace() for c in s):
        return False
    if not (6 <= len(s) <= 20):
        return False
    digit_count = sum(1 for c in s if c in string.digits)
    return digit_count >= 2

import string

def meets_distinct_class_count_policy(s):
    if len(s) < 8:
        return False
    classes = 0
    if any(c in string.ascii_lowercase for c in s):
        classes += 1
    if any(c in string.ascii_uppercase for c in s):
        classes += 1
    if any(c in string.digits for c in s):
        classes += 1
    if any(not c.isalnum() for c in s):
        classes += 1
    return classes >= 3

def is_not_common_password(s, common_list):
    if len(s) < 8:
        return False
    s_lower = s.lower()
    for c in common_list:
        if s_lower == c.lower():
            return False
    return True

def meets_length_no_whitespace_policy(s):
    if not (8 <= len(s) <= 32):
        return False
    return not any(c.isspace() for c in s)

def has_no_sequential_run(s):
    if len(s) < 3:
        return True
    run = 1
    for i in range(1, len(s)):
        if ord(s[i]) == ord(s[i - 1]) + 1:
            run += 1
            if run >= 3:
                return False
        else:
            run = 1
    return True

def is_valid_24h_time(s):
    parts = s.split(':')
    if len(parts) != 3:
        return False
    h, m, sec = parts
    if not (len(h) == 2 and h.isdigit() and len(m) == 2 and m.isdigit() and len(sec) == 2 and sec.isdigit()):
        return False
    h, m, sec = int(h), int(m), int(sec)
    return 0 <= h <= 23 and 0 <= m <= 59 and 0 <= sec <= 59
